macro_rules! deps {
    () => {
        Match!();
        Cache!();
        Regex!();
    };
}

macro_rules! Pool {
    () => {
        deps!();
        # [doc = " A thread safe pool that works in an `alloc`-only context."] # [doc = ""] # [doc = " Getting a value out comes with a guard. When that guard is dropped, the"] # [doc = " value is automatically put back in the pool. The guard provides both a"] # [doc = " `Deref` and a `DerefMut` implementation for easy access to an underlying"] # [doc = " `T`."] # [doc = ""] # [doc = " A `Pool` impls `Sync` when `T` is `Send` (even if `T` is not `Sync`). This"] # [doc = " is possible because a pool is guaranteed to provide a value to exactly one"] # [doc = " thread at any time."] # [doc = ""] # [doc = " Currently, a pool never contracts in size. Its size is proportional to the"] # [doc = " maximum number of simultaneous uses. This may change in the future."] # [doc = ""] # [doc = " A `Pool` is a particularly useful data structure for this crate because"] # [doc = " many of the regex engines require a mutable \"cache\" in order to execute"] # [doc = " a search. Since regexes themselves tend to be global, the problem is then:"] # [doc = " how do you get a mutable cache to execute a search? You could:"] # [doc = ""] # [doc = " 1. Use a `thread_local!`, which requires the standard library and requires"] # [doc = " that the regex pattern be statically known."] # [doc = " 2. Use a `Pool`."] # [doc = " 3. Make the cache an explicit dependency in your code and pass it around."] # [doc = " 4. Put the cache state in a `Mutex`, but this means only one search can"] # [doc = " execute at a time."] # [doc = " 5. Create a new cache for every search."] # [doc = ""] # [doc = " A `thread_local!` is perhaps the best choice if it works for your use case."] # [doc = " Putting the cache in a mutex or creating a new cache for every search are"] # [doc = " perhaps the worst choices. Of the remaining two choices, whether you use"] # [doc = " this `Pool` or thread through a cache explicitly in your code is a matter"] # [doc = " of taste and depends on your code architecture."] # [doc = ""] # [doc = " # Warning: may use a spin lock"] # [doc = ""] # [doc = " When this crate is compiled _without_ the `std` feature, then this type"] # [doc = " may used a spin lock internally. This can have subtle effects that may"] # [doc = " be undesirable. See [Spinlocks Considered Harmful][spinharm] for a more"] # [doc = " thorough treatment of this topic."] # [doc = ""] # [doc = " [spinharm]: https://matklad.github.io/2020/01/02/spinlocks-considered-harmful.html"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to share a single hybrid regex among multiple"] # [doc = " threads, while also safely getting exclusive access to a hybrid's"] # [doc = " [`Cache`](crate::hybrid::regex::Cache) without preventing other searches"] # [doc = " from running while your thread uses the `Cache`."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::regex::{Cache, Regex},"] # [doc = "     util::{lazy::Lazy, pool::Pool},"] # [doc = "     Match,"] # [doc = " };"] # [doc = ""] # [doc = " static RE: Lazy<Regex> ="] # [doc = "     Lazy::new(|| Regex::new(\"foo[0-9]+bar\").unwrap());"] # [doc = " static CACHE: Lazy<Pool<Cache>> ="] # [doc = "     Lazy::new(|| Pool::new(|| RE.create_cache()));"] # [doc = ""] # [doc = " let expected = Some(Match::must(0, 3..14));"] # [doc = " assert_eq!(expected, RE.find(&mut CACHE.get(), b\"zzzfoo12345barzzz\"));"] # [doc = " ```"] pub struct Pool < T , F = fn () -> T > (alloc :: boxed :: Box < inner :: Pool < T , F > >) ;
    };
}

Pool!();